{"content": "#!/usr/bin/env python3
"""Check CP1252 encoding table."""
import codecs

undecodable = []
table = {}
for b in range(256):
    try:
        char = bytes([b]).decode('cp1252')
        cp = ord(char)
        table[b] = cp
    except UnicodeDecodeError:
        undecodable.append(b)
        table[b] = None

print(f"Undecodable bytes: {[hex(b) for b in undecodable]}")

# Build reverse table
reverse = {}
for b, cp in table.items():
    if cp is not None:
        if cp in reverse:
            print(f"Warning: duplicate cp U+{cp:04X} from bytes 0x{reverse[cp]:02X} and 0x{b:02X}")
        reverse[cp] = b

print(f"Reverse table size: {len(reverse)} entries")
print(f"Non-ASCII entries: {sorted([(hex(b), hex(cp)) for b, cp in table.items() if cp and cp > 127], key=lambda x: x[0])}")
", "path": "check_cp1252.py"}

